import { ChangeDetectionStrategy, Component } from '@angular/core';
import { AevkoDialog, AevkoDialogBase } from '../dialog';

@Component({
  selector: 'aevko-drawer',
  standalone: true,
  imports: [AevkoDialog],
  templateUrl: './drawer.component.html',
  styleUrl: './drawer.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'drawer-root', '(click)': 'handleClick($event)' },
})
export class AevkoDrawer extends AevkoDialogBase {
  constructor() {
    super('aevkoDrawerTrigger', 'aevkoDrawerClose');
  }
}

:host {
  display: contents;
}
.handle {
  background: var(--aevko-border, #a3a3a3);
  block-size: 0.25rem;
  inline-size: 3rem;
  margin: -0.5rem auto 1rem;
}
